// Fetch the uploaded file metadata directly from 'Upload file' — the
// 'Share file' node's output is a permission resource, not file metadata,
// so we read name/webViewLink from the upload step instead (same item count,
// Share runs first to guarantee the link is open before we log/send it).
const items = $('Upload file').all();
const attachmentList = [];

items.forEach(item => {
    // Access item JSON data aggregated from the Google Drive node
    const data = item.json;

    // Handle whether Aggregate outputted an array or individual item objects
    const fileArray = Array.isArray(data) ? data : (data.data || [data]);

    fileArray.forEach(file => {
        // Skip execution metadata or items without a webViewLink
        if (!file || !file.webViewLink) return;

        const fileName = file.name || file.fileName || 'Attachment';
        const fileUrl = file.webViewLink;

        attachmentList.push({
            name: fileName,
            url: fileUrl
        });
    });
});

// Return as a formatted JSON string for Postgres $3 parameter
return [{
    json: {
        attachments_json: JSON.stringify(attachmentList)
    }
}];

// Access the binary data generated in the 'format base64' node
const base64NodeItem = $('format base64').first();
const binaryObject = base64NodeItem.binary || {};
const binaryKeys = Object.keys(binaryObject);

// If no attachments were passed, forward a single clean JSON item
if (binaryKeys.length === 0) {
    return [{
        json: { ...$input.first().json, has_attachments: false }
    }];
}

// Split each binary key into its own n8n item for Google Drive upload
const outputItems = binaryKeys.map(key => {
    return {
        json: {
            ...$input.first().json,
            target_binary_key: key,
            has_attachments: true
        },
        binary: {
            // Standardize the binary key to 'data' for the Google Drive node
            data: binaryObject[key]
        }
    };
});

return outputItems;

const body = $('Webhook').first().json.body || $('Webhook').first().json;
const attachments = body.attachments || [];

const binaryData = {};

if (Array.isArray(attachments) && attachments.length > 0) {
    attachments.forEach((att, index) => {
        // Frontend sends { name, url } where url is a data: URL
        // (e.g. 'data:application/pdf;base64,JVBERi0...') from FileReader.
        const match = /^data:([^;,]+)?(?:;[^,]*)?,(.*)$/s.exec(att.url || '');
        if (!match) return;
        const [, mimeType, base64] = match;

        // Use 'data' for the first item if there's only 1, or attachment_0, attachment_1
        const key = attachments.length === 1 ? 'data' : `attachment_${index}`;

        binaryData[key] = {
            data: base64,
            mimeType: mimeType || 'application/octet-stream',
            fileName: att.name || `attachment_${index}`
        };
    });
}

return [
    {
        json: body,
        binary: binaryData
    }
];

function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
function escapeHtml(s) {
  return (s || '').toString()
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
}
function toTitleCase(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
function money(n) { return n != null && n !== '' ? '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : ''; }
function dateStr(d) { return d ? new Date(d).toLocaleDateString() : ''; }

// A tracking pixel only works in an HTML email — the two Gmail nodes
// downstream switched from emailType 'text' to 'html' alongside this.
// contact_id always comes straight from the webhook body here (this is
// the manual "Email Contact" send, always initiated FROM a contact).
// Source data comes from 'format base64' rather than $json/$input because
// intervening Postgres lookups (like every other Postgres lookup in this
// workflow) don't pass through the original item's fields or binary data
// — only a named-node reference does.
const source = $('format base64').item.json;
const contactId = Number(source.contact_id);
const pixelId = genId();
const pixelUrl = `${safeEnv('N8N_WEBHOOK_BASE_URL')}/webhook/track-email-open?id=${pixelId}&contact_id=${contactId}`;
const pixelTag = `<img src="${pixelUrl}" width="1" height="1" style="display:none" alt="" />`;
const unsubToken = $('Get Unsubscribe Token').item.json.unsubscribe_token || '';
const unsubUrl = safeEnv('FRONTEND_BASE_URL') + '/unsubscribe/' + unsubToken;
const footer = `<br><br><span style="font-size:11px;color:#94a3b8">Don't want these emails? <a href="${unsubUrl}">Unsubscribe</a></span>`;

// Dynamic-field substitution — resolves tokens a manual send previously
// couldn't (e.g. {{appointment.start_time}}), using the Dynamic Fields:*
// lookup nodes upstream (each alwaysOutputData:true so a contact with no
// deal/activity still yields an item, just with null columns, instead of
// crashing this node on a missing item). {{company_name}} (the SENDER's
// own company) is deliberately left untouched here — the two Gmail nodes
// still substitute that themselves via Get Company Name: message/message1,
// same as before this change; only {{company.name}} (the CONTACT's own
// company) is resolved here.
const contactFields = $('Dynamic Fields: Contact').item.json;
const pipelineFields = $('Dynamic Fields: Pipeline').item.json;
const stageFields = $('Dynamic Fields: Pipeline Stage').item.json;
const activityFields = $('Dynamic Fields: Activities').item.json;
const contactTz = contactFields?.timezone || 'America/New_York';
const appointmentTime = activityFields?.due_at
  ? DateTime.fromISO(activityFields.due_at, { zone: 'utc' }).setZone(contactTz).toFormat("EEEE, MMMM d 'at' h:mm a")
  : '';

function fillDynamicFields(t) {
  return (t || '')
    .replace(/{{\s*appointment\.start_time\s*}}/gi, appointmentTime)
    .replace(/{{\s*appointment\.title\s*}}/gi, activityFields?.subject || '')
    .replace(/{{\s*appointment\.location\s*}}/gi, activityFields?.location || '')
    .replace(/{{\s*company\.name\s*}}/gi, toTitleCase(contactFields?.company_name))
    .replace(/{{\s*opportunity\.name\s*}}/gi, pipelineFields?.name || '')
    .replace(/{{\s*opportunity\.value\s*}}/gi, money(pipelineFields?.deal_value))
    .replace(/{{\s*opportunity\.stage\s*}}/gi, stageFields?.name || '')
    .replace(/{{\s*opportunity\.pipeline\s*}}/gi, pipelineFields?.pipeline_name || '')
    .replace(/{{\s*opportunity\.due_at\s*}}/gi, dateStr(pipelineFields?.expected_close));
}

const filledSubject = fillDynamicFields(source.subject || '');
const filledMessage = fillDynamicFields(source.message || '');
const htmlMessage = escapeHtml(filledMessage).replace(/\n/g, '<br>') + pixelTag + footer;
return [{ json: { ...source, subject: filledSubject, htmlMessage, pixelId }, binary: $('format base64').item.binary }];

// Postgres nodes (Get Company Name: message) don't pass through binary data,
// so re-attach the attachment binary that survived up to 'Prepare HTML Email'
// before Gmail's attachmentsUi reads $binary on this item.
return [{ json: $input.item.json, binary: $('Prepare HTML Email').item.binary }];

